// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.io.File;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.RepositoryException;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.SailConnection;
import org.eclipse.rdf4j.sail.SailException;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * A read attempt that cannot be restarted while its result is registered fails the way every other Sail read failure
 * does: as a {@link SailException}, which the repository layer then reports as a {@link RepositoryException}.
 */
class LmdbReadRegistrationFailureTest {

	@Test
	void failedRestartDuringRegistrationIsASailException(@TempDir File dataDir) {
		LmdbStore store = new LmdbStore(dataDir);
		store.init();
		try (SailConnection connection = store.getConnection()) {
			SailException restartFailure = new SailException("restart failed");
			((LmdbStoreConnection) connection).beforeIterationRegistrationForTest = () -> {
				throw restartFailure;
			};
			connection.begin(IsolationLevels.SNAPSHOT);
			SailException failure = assertThrows(SailException.class,
					() -> connection.getStatements(null, null, null, false));
			assertSame(restartFailure, failure, "the restart failure is reported unchanged");
			connection.rollback();
		} finally {
			store.shutDown();
		}
	}

	@Test
	void failedRestartDuringRegistrationIsARepositoryException(@TempDir File dataDir) {
		SailRepository repository = new SailRepository(new LmdbStore(dataDir));
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			SailConnection sailConnection = ((SailRepositoryConnection) connection).getSailConnection();
			SailException restartFailure = new SailException("restart failed");
			((LmdbStoreConnection) sailConnection).beforeIterationRegistrationForTest = () -> {
				throw restartFailure;
			};
			connection.begin();
			RepositoryException failure = assertThrows(RepositoryException.class,
					() -> connection.getStatements(null, null, null, false));
			assertEquals(restartFailure, failure.getCause(), "the repository layer wraps the Sail failure");
			connection.rollback();
		} finally {
			repository.shutDown();
		}
	}
}
